@@ -1033,16 +1024,8 @@ xmlBufResetInput(xmlBufPtr buf, xmlParserInputPtr input) {
  */
 int
 xmlBufUpdateInput(xmlBufPtr buf, xmlParserInputPtr input, size_t pos) {
-    if (input == NULL)
-        return(-1);
-    /*
-     * TODO: It might be safer to keep using the buffer content if there
