-    if ((buf == NULL) || (buf->error)) {
-        input->base = input->cur = input->end = BAD_CAST "";
+    if ((buf == NULL) || (input == NULL))
         return(-1);
-    }
     CHECK_COMPAT(buf)
     input->base = buf->content;
